<script setup lang="ts">
import {computed} from 'vue';import {advise} from '../engine/advice';import type {Result,Scenario} from '../types';
const props=defineProps<{result:Result;scenario:Scenario}>();const advice=computed(()=>advise(props.result,props.scenario));const pct=(n:number)=>(n*100).toFixed(1)+'%';const range=computed(()=>[Math.max(0,props.result.equity-1.96*props.result.se),Math.min(1,props.result.equity+1.96*props.result.se)]);
</script>
<template><section class="panel result" aria-live="polite"><header><h2>权益分析</h2><span class="tag">{{result.method==='exact'?'精确枚举':'蒙特卡洛'}}</span></header><div class="equity-top"><div class="ring" :style="{background:`conic-gradient(var(--accent) ${result.equity*360}deg, #243342 0deg)`}"><div><strong>{{pct(result.equity)}}</strong><small>底池权益</small></div></div><div class="result-caption"><strong>已计入平分份额</strong><p class="muted">{{result.samples.toLocaleString()}} {{result.method==='exact'?'个合法状态':'次模拟'}}</p><p class="muted" v-if="result.method!=='exact'">约 95% 抽样区间<br>{{pct(range[0])}} – {{pct(range[1])}}</p><p class="muted" v-else>模型内无抽样误差</p></div></div><div class="prob-bar" aria-label="独赢、平局和输牌概率"><span :style="{width:pct(result.win)}"></span><span :style="{width:pct(result.tie)}"></span><span :style="{width:pct(1-result.win-result.tie)}"></span></div><div class="legend"><span>● 独赢 {{pct(result.win)}}</span><span>● 平局 {{pct(result.tie)}}</span><span>● 输牌 {{pct(1-result.win-result.tie)}}</span></div><div class="metrics" v-if="advice.threshold!==null"><div><small>直接跟注门槛</small><strong>{{pct(advice.threshold)}}</strong></div><div><small>简化跟注 EV</small><strong>{{advice.ev?.toFixed(2)}}</strong></div></div><div class="advice"><small>当前行动参考</small><h3>{{advice.title}}</h3><p>{{advice.text}}</p></div><p class="muted warning">计算使用你设定的范围，未知对手默认为随机。抽样区间不代表范围准确度。不支持边池或 ICM；抽水按你的设置处理。精确权益也不等于精确策略。</p></section></template>
